int mirrorCommitCount(const QString &mirrorPath, const QString &branch)
{
    if (mirrorPath.trimmed().isEmpty() || branch.isEmpty() ||
        !QDir(mirrorPath).exists())
        return -1;
    return mirrorTipMemoized<int>(mirrorPath, branch, QStringLiteral("commits"), [&] {
        QByteArray out;
        if (!runGitCapture(mirrorPath, {"rev-list", "--count", branch}, &out,
                           nullptr))
            return -1;
        bool ok = false;
        const int n = QString::fromUtf8(out).trimmed().toInt(&ok);
        return ok ? n : -1;
    });
}

