CommitIdentity gitCommitIdentity(const QString &gitPath,
                                        const QString &commit)
{
    CommitIdentity identity;
    if (gitPath.trimmed().isEmpty() || commit.trimmed().isEmpty() ||
        !QDir(gitPath).exists())
        return identity;
    // A commit's subject/author/date never change: one `git show` per object
    // name, process-wide. The catalog pass asked for the same tip every round.
    static QHash<QString, CommitIdentity> cache;
    static QMutex cacheMutex;
    const QString key = gitPath + QLatin1Char('\n') + commit.trimmed();
    {
        QMutexLocker lock(&cacheMutex);
        const auto cached = cache.constFind(key);
        if (cached != cache.constEnd())
            return cached.value();
    }
    QByteArray out;
    if (!runGitCapture(gitPath,
                       {"show", "-s", "--format=%s%n%an%n%ct", commit}, &out,
                       nullptr))
        return identity;
    const QStringList lines = QString::fromUtf8(out).split('\n');
    if (lines.size() < 3)
        return identity;
    identity.subject = lines.at(0).trimmed().left(kMaxCommitSubjectChars);
    identity.author = lines.at(1).trimmed().left(kMaxCommitAuthorChars);
    identity.committedAtMs =
        qMax(qint64(0), lines.at(2).trimmed().toLongLong() * 1000);
    if (identity.subject.isEmpty() && identity.author.isEmpty())
        return identity; // not cached: the object may simply not be here yet
    QMutexLocker lock(&cacheMutex);
    if (cache.size() > 4096)
        cache.clear();
    cache.insert(key, identity);
    return identity;
}

CommitIdentity mirrorCommitIdentity(const QString &mirrorPath,
                                           const QString &workTreePath,
                                           const QString &commit)
{
    CommitIdentity identity = gitCommitIdentity(mirrorPath, commit);
    if (identity.subject.isEmpty() && identity.author.isEmpty())
        identity = gitCommitIdentity(workTreePath, commit);
    return identity;
}

QJsonArray mirrorGitActivityWeeks(const QString &mirrorPath,
                                         const QString &branch,
                                         bool mergesOnly)
{
    constexpr int kWeeks = 52;
    constexpr qint64 kWeekSeconds = 7LL * 24LL * 60LL * 60LL;
    QVector<int> buckets(kWeeks, 0);
    auto toArray = [&buckets]() {
        QJsonArray arr;
        for (int n : buckets)
            arr.append(n);
        return arr;
    };

    if (mirrorPath.trimmed().isEmpty() || branch.trimmed().isEmpty() ||
        !QDir(mirrorPath).exists())
        return toArray();
    QByteArray out;
    QStringList arguments = {
        QStringLiteral("log"), QStringLiteral("--since=52 weeks ago"),
        QStringLiteral("--format=%ct")};
    if (mergesOnly)
        arguments << QStringLiteral("--merges");
    arguments << branch << QStringLiteral("--");
    if (!runGitCapture(mirrorPath, arguments, &out, nullptr))
        return toArray();

    const qint64 now = QDateTime::currentSecsSinceEpoch();
    const qint64 start = now - (qint64(kWeeks) * kWeekSeconds);
    for (const QByteArray &line : out.split('\n')) {
        bool ok = false;
        const qint64 ts = QString::fromUtf8(line).trimmed().toLongLong(&ok);
        if (!ok)
            continue;
        const int idx =
            qBound(0, int((ts - start) / kWeekSeconds), kWeeks - 1);
        buckets[idx] += 1;
    }
    return toArray();
}

QJsonArray mirrorCommitActivityWeeks(const QString &mirrorPath,
                                            const QString &branch)
{
    return mirrorTipMemoized<QJsonArray>(
        mirrorPath, branch, QStringLiteral("activity"),
        [&] { return mirrorGitActivityWeeks(mirrorPath, branch, false); },
        QString::number(QDate::currentDate().toJulianDay()));
}

QJsonArray mirrorMergeActivityWeeks(const QString &mirrorPath,
                                           const QString &branch)
{
    return mirrorTipMemoized<QJsonArray>(
        mirrorPath, branch, QStringLiteral("merge-activity"),
        [&] { return mirrorGitActivityWeeks(mirrorPath, branch, true); },
        QString::number(QDate::currentDate().toJulianDay()));
}

int mirrorBranchCount(const QString &mirrorPath)
{
    if (mirrorPath.trimmed().isEmpty() || !QDir(mirrorPath).exists())
        return -1;
    // Keyed by the refs stamp rather than one tip: any branch moving changes
    // the answer, and the stamp is a handful of stats versus a process.
    struct Entry {
        QString stamp;
        int count = -1;
    };
    static QHash<QString, Entry> cache;
    static QMutex mutex;
    const QString stamp = gitRefsDirSignature(mirrorPath);
    {
        QMutexLocker lock(&mutex);
        const auto cached = cache.constFind(mirrorPath);
        if (cached != cache.constEnd() && !stamp.isEmpty() &&
            cached->stamp == stamp)
            return cached->count;
    }
    QByteArray out;
    if (!runGitCapture(mirrorPath,
                       {"for-each-ref", "--format=%(refname)", "refs/heads/"}, &out,
                       nullptr))
        return -1;
    int count = 0;
    for (const QByteArray &line : out.split('\n')) {
        const QByteArray ref = line.trimmed();
        if (ref.isEmpty() || ref == "refs/heads/forkmesh/pulls" ||
            ref.startsWith("refs/heads/forkmesh/pull/"))
            continue;
        ++count;
    }
    QMutexLocker lock(&mutex);
    cache.insert(mirrorPath, Entry{stamp, count});
    return count;
}

int mirrorWorktreeCount(const QString &localPath)
{
    if (localPath.trimmed().isEmpty() || !QDir(localPath).exists())
        return -1;
    QByteArray out;
    if (!cachedWorktreeListPorcelain(localPath, &out))
        return -1;
    int count = 0;
    for (const QByteArray &line : out.split('\n'))
        if (line.startsWith("worktree "))
            ++count;
    return count;
}

QString liveGitIndexPath(const QString &dir)
{
    const QFileInfo dotGit(dir + QStringLiteral("/.git"));
    if (dotGit.isDir())
        return dotGit.absoluteFilePath() + QStringLiteral("/index");
    if (!dotGit.isFile())
        return QString();
    QFile pointer(dotGit.absoluteFilePath());
    if (!pointer.open(QIODevice::ReadOnly))
        return QString();
    const QByteArray line = pointer.readLine().trimmed();
    static const QByteArray prefix("gitdir: ");
    if (!line.startsWith(prefix))
        return QString();
    QString gitDir = QString::fromUtf8(line.mid(prefix.size())).trimmed();
    if (gitDir.isEmpty())
        return QString();
    if (QDir::isRelativePath(gitDir))
        gitDir = QDir(dir).absoluteFilePath(gitDir);
    return QDir::cleanPath(gitDir + QStringLiteral("/index"));
}

bool seedSnapshotIndexFromWorktree(const QString &dir, const QString &indexPath,
                                          QString *livePath)
{
    const QString live = liveGitIndexPath(dir);
    if (livePath)
        *livePath = live;
    if (live.isEmpty() || !QFileInfo(live).isFile())
        return false;
    QFile::remove(indexPath);
    return QFile::copy(live, indexPath);
}

bool buildWorkingTreeDiff(const QString &dir, const QString &base, QByteArray *out,
                          QString *err)
{
    if (!QDir(dir).exists()) {
        // git would print "cannot change to '<dir>'" twice here (the staging pass
        // retries on a missing path); say what actually happened instead.
        if (err)
            *err = QStringLiteral("The worktree at %1 is gone.").arg(dir);
        return false;
    }
    QTemporaryDir temp;
    if (!temp.isValid()) {
        if (err)
            *err = QStringLiteral("Could not create a temporary Git index.");
        return false;
    }
    const QString indexPath = temp.path() + QStringLiteral("/index");

    QProcessEnvironment env = QProcessEnvironment::systemEnvironment();
    env.insert(QStringLiteral("GIT_INDEX_FILE"), indexPath);

    QByteArray ignored;
    // Seeded from the live index when there is one (fast: only changed files
    // are hashed); the base tree is the cold fallback.
    bool lastSeeded = false; // whether the latest attempt used the live index
    auto stageSnapshot = [&](bool seed) {
        lastSeeded = seed && seedSnapshotIndexFromWorktree(dir, indexPath);
        if (!lastSeeded) {
            if (!runGitCaptureWithEnv(dir, {"read-tree", base}, env, &ignored, err))
                return false;
        }
        return runGitCaptureWithEnv(dir, {"add", "-A", "--", "."}, env,
                                    &ignored, err);
    };
    if (!stageSnapshot(/*seed=*/true)) {
        const QString firstError = err ? *err : QString();
        const bool racedDeletion =
            firstError.contains(QStringLiteral("unable to stat"),
                                Qt::CaseInsensitive) ||
            firstError.contains(QStringLiteral("No such file"),
                                Qt::CaseInsensitive);
        // A vanished file is retried the fast way; a seeded attempt that
        // failed for any other reason (an index git would not read, say)
        // gets one cold rebuild from the base tree.
        if (!racedDeletion && !lastSeeded)
            return false;
        if (!stageSnapshot(/*seed=*/racedDeletion))
            return false;
    }
    return runGitCaptureWithEnv(dir, {"diff", "--binary", "--cached", base}, env, out, err);
}

bool isGitWorkingTreeRoot(const QString &dir)
{
    if (dir.trimmed().isEmpty() || !QDir(dir).exists())
        return false;
    const QString index = liveGitIndexPath(dir);
    return !index.isEmpty() && QFileInfo(QFileInfo(index).path()).isDir();
}

bool ensureGitCommitGraph(const QString &dir)
{
    if (dir.trimmed().isEmpty())
        return false;
    static QMutex mutex;
    static QSet<QString> tried;
    {
        QMutexLocker lock(&mutex);
        if (tried.contains(dir))
            return false;
        tried.insert(dir);
    }
    QByteArray common;
    if (!runGitCapture(dir, {"rev-parse", "--git-common-dir"}, &common, nullptr))
        return false;
    QString commonDir = QString::fromUtf8(common).trimmed();
    if (commonDir.isEmpty())
        return false;
    if (QDir::isRelativePath(commonDir))
        commonDir = QDir(dir).absoluteFilePath(commonDir);
    const QString info = QDir::cleanPath(commonDir + QStringLiteral("/objects/info"));
    const QDateTime staleBefore = QDateTime::currentDateTime().addDays(-1);
    for (const QString &graph :
         {info + QStringLiteral("/commit-graph"),
          info + QStringLiteral("/commit-graphs/commit-graph-chain")}) {
        const QFileInfo file(graph);
        if (file.isFile() && file.lastModified() > staleBefore)
            return false;
    }
    return runGitCapture(dir,
                         {"commit-graph", "write", "--reachable", "--split",
                          "--no-progress"},
                         nullptr, nullptr);
}

QString pillTextColor(const QString &backgroundHex)
{
    const QColor c(backgroundHex);
    const double luminance =
        0.299 * c.red() + 0.587 * c.green() + 0.114 * c.blue();
    return luminance > 150 ? QStringLiteral("#1f2328") : QStringLiteral("#ffffff");
}

QString faviconRootPath()
{
    return QStringLiteral("/favicon.ico");
}

QString faviconAssetPath()
{
    return QStringLiteral("/favicon/favicon.ico");
}

bool hostCannotServePublicFavicon(const QString &host)
{
    const QString h = host.trimmed().toLower();
    if (h.isEmpty())
        return true;
    QUrl probe;
    probe.setHost(h);
    if (probe.host().isEmpty())
        return true;
    // RFC 2606 / RFC 6761 reserved names, plus the ICANN-reserved .internal.
    for (const QLatin1String suffix :
         {QLatin1String(".internal"), QLatin1String(".invalid"),
          QLatin1String(".example"), QLatin1String(".test")}) {
        if (h.endsWith(suffix))
            return true;
    }
    return h == QLatin1String("invalid") || h == QLatin1String("example") ||
           h == QLatin1String("test") || h == QLatin1String("api.vultr.com");
}

QUrl faviconUrl(const QString &serverUrl)
{
    const QUrl url(serverUrl);
    if (url.host().isEmpty())
        return {};
    QUrl out;
    out.setScheme(url.scheme() == QStringLiteral("ws") ? QStringLiteral("http")
                                                       : QStringLiteral("https"));
    out.setHost(url.host());
    if (url.port() > 0)
        out.setPort(url.port());
    out.setPath(faviconRootPath());
    return out;
}

QUrl faviconAssetUrl(const QUrl &url)
{
    QUrl out(url);
    out.setPath(faviconAssetPath());
    return out;
}

QString faviconCacheDir()
{
    return forkmesh::paths::dataRoot() +
           "/favicons";
}

QString faviconCachePath(const QString &host)
{
    QString safe = host;
    safe.replace(QRegularExpression("[^a-zA-Z0-9._-]"), "_");
    return faviconCacheDir() + "/" + safe + ".png";
}

QPixmap withPresenceDot(const QPixmap &face, const QColor &dot,
                        const QColor &ring)
{
    if (face.isNull())
        return face;
    QPixmap out = face;
    const QSizeF size = out.deviceIndependentSize();
    const qreal side = qMin(size.width(), size.height());
    const qreal ringWidth = qMax<qreal>(2.0, side * 0.09);
    const qreal diameter = side * 0.3125;
    const QRectF dotRect(size.width() - diameter - ringWidth * 0.25,
                         size.height() - diameter - ringWidth * 0.25, diameter,
                         diameter);
    QPainter p(&out);
    p.setRenderHint(QPainter::Antialiasing);
    p.setCompositionMode(QPainter::CompositionMode_Source);
    p.setPen(Qt::NoPen);
    p.setBrush(ring);
    p.drawEllipse(dotRect.adjusted(-ringWidth, -ringWidth, ringWidth, ringWidth));
    p.setCompositionMode(QPainter::CompositionMode_SourceOver);
    p.setBrush(dot);
    p.drawEllipse(dotRect);
    return out;
}

QPixmap roundedRectPixmap(const QPixmap &src, int side, qreal radius)
{
    const qreal dpr = iconDevicePixelRatio();
    QPixmap out = crispIconPixmap(side, dpr);
    if (src.isNull())
        return out;
    QPainter p(&out);
    p.setRenderHint(QPainter::Antialiasing);
    p.setRenderHint(QPainter::SmoothPixmapTransform);
    QPainterPath path;
    path.addRoundedRect(QRectF(0, 0, side, side), radius, radius);
    p.setClipPath(path);
    QPixmap scaled = src.scaled(out.width(), out.height(),
                                Qt::KeepAspectRatioByExpanding,
                                Qt::SmoothTransformation);
    scaled.setDevicePixelRatio(dpr);
    const QSizeF ls = scaled.deviceIndependentSize();
    p.drawPixmap(QPointF((side - ls.width()) / 2.0, (side - ls.height()) / 2.0),
                 scaled);
    return out;
}

QPixmap roundedBannerPixmap(const QPixmap &src, int w, int h, qreal radius)
{
    const qreal dpr = iconDevicePixelRatio();
    QPixmap out = crispIconPixmap(w, h, dpr);
    if (src.isNull() || w <= 0 || h <= 0)
        return out;
    QPainter p(&out);
    p.setRenderHint(QPainter::Antialiasing);
    p.setRenderHint(QPainter::SmoothPixmapTransform);
    QPainterPath path;
    path.addRoundedRect(QRectF(0, 0, w, h), radius, radius);
    p.setClipPath(path);
    QPixmap scaled = src.scaled(out.width(), out.height(),
                                Qt::KeepAspectRatioByExpanding,
                                Qt::SmoothTransformation);
    scaled.setDevicePixelRatio(dpr);
    const QSizeF ls = scaled.deviceIndependentSize();
    p.drawPixmap(QPointF((w - ls.width()) / 2.0, (h - ls.height()) / 2.0), scaled);
    return out;
}

QPixmap languageBarPixmap(const QList<QPair<QString, qint64>> &langs,
                          qint64 total, int shown, int w, int h)
{
    QPixmap out = crispIconPixmap(w, h, iconDevicePixelRatio());
    if (total <= 0 || shown <= 0 || w <= 0 || h <= 0)
        return out;
    QPainter p(&out);
    p.setRenderHint(QPainter::Antialiasing);
    QPainterPath clip;
    clip.addRoundedRect(QRectF(0, 0, w, h), h / 2.0, h / 2.0);
    p.setClipPath(clip);
    p.fillRect(QRectF(0, 0, w, h), Theme::remapColor(QColor("#30363d"))); // track behind segments
    double x = 0;
    for (int i = 0; i < shown && i < langs.size(); ++i) {
        const double seg = double(langs.at(i).second) / total * w;
        p.fillRect(QRectF(x, 0, seg + 1, h),
                   QColor(languageColor(langs.at(i).first)));
        x += seg;
    }
    return out;
}

QPixmap letterFavicon(const QString &host, int side)
{
    QPixmap pixmap = crispIconPixmap(side, iconDevicePixelRatio());
    QPainter painter(&pixmap);
    painter.setRenderHint(QPainter::Antialiasing);
    const uint hash = qHash(host);
    painter.setPen(Qt::NoPen);
    painter.setBrush(QColor(Theme::kSenderPalette[hash % Theme::kSenderPaletteSize]));
    painter.drawRoundedRect(QRectF(0, 0, side, side), side * 0.25, side * 0.25);
    const QChar letter = host.isEmpty() ? QChar('?') : host.at(0).toUpper();
    QFont font = painter.font();
    font.setPixelSize(qMax(8, qRound(side * 0.5)));
    font.setBold(true);
    painter.setFont(font);
    painter.setPen(QColor("#0f172a"));
    painter.drawText(QRect(0, 0, side, side), Qt::AlignCenter, QString(letter));
    return pixmap;
}

QString builtinFaviconKey(const QString &host)
{
    const QString h = host.toLower();
    // ForkMesh mirror gateways deliberately serve repository transport only;
    // they do not host the relay's static favicon.  Use the packaged mark for
    // ForkMesh hosts before any network request so a mirror never receives a
    // doomed /favicon.ico (or /favicon/favicon.ico fallback) request.
    if (h == QStringLiteral("forkmesh.com") || h.endsWith(".forkmesh.com"))
        return QStringLiteral("forkmesh");
    if (h == QStringLiteral("anthropic.com") || h.endsWith(".anthropic.com") ||
        h == QStringLiteral("claude.ai") || h.endsWith(".claude.ai"))
        return QStringLiteral("anthropic");
    if (h == QStringLiteral("api.mainnet-beta.solana.com"))
        return QStringLiteral("solana");
    return {};
}

bool hasBuiltinFavicon(const QString &host)
{
    return !builtinFaviconKey(host).isEmpty();
}

QPixmap builtinFavicon(const QString &host, int side)
{
    const QString key = builtinFaviconKey(host);
    if (key.isEmpty() || side <= 0)
        return {};
    if (key == QStringLiteral("forkmesh")) {
        const QPixmap logo(QStringLiteral(":/app/forkmesh.png"));
        return logo.isNull() ? QPixmap() : roundedRectPixmap(logo, side, side / 4.0);
    }
    QPixmap pixmap = crispIconPixmap(side, iconDevicePixelRatio());
    QPainter painter(&pixmap);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setPen(Qt::NoPen);
    painter.setBrush(key == QStringLiteral("solana")
                         ? QColor("#17172e") // Solana navy
                         : QColor("#d97757")); // Anthropic clay
    painter.drawRoundedRect(QRectF(0, 0, side, side), side / 4.0, side / 4.0);
    if (key == QStringLiteral("solana")) {
        QPen stroke(QColor("#14f195"));
        stroke.setWidthF(qMax(1.0, side * 0.11));
        stroke.setCapStyle(Qt::RoundCap);
        painter.setPen(stroke);
        const qreal inset = side * 0.25;
        const qreal width = side * 0.5;
        for (const qreal y : {side * 0.32, side * 0.50, side * 0.68})
            painter.drawLine(QPointF(inset, y), QPointF(inset + width, y));
        return pixmap;
    }
    QPen stroke(QColor("#ffffff"));
    stroke.setWidthF(qMax(1.0, side * 0.09));
    stroke.setCapStyle(Qt::RoundCap);
    painter.setPen(stroke);
    const QPointF center(side / 2.0, side / 2.0);
    const qreal radius = side * 0.28;
    for (int i = 0; i < 6; ++i) {
        const qreal angle = qDegreesToRadians(qreal(i) * 30.0);
        const QPointF arm(radius * std::cos(angle), radius * std::sin(angle));
        painter.drawLine(center - arm, center + arm);
    }
    return pixmap;
}

QString autostartDesktopPath()
{
    return QStandardPaths::writableLocation(QStandardPaths::GenericConfigLocation) +
           "/autostart/forkmesh.desktop";
}

bool isAutostartEnabled()
{
#if defined(Q_OS_WIN)
    QSettings run(kWinRunKey, QSettings::NativeFormat);
    return run.contains("ForkMesh");
#elif defined(Q_OS_MACOS)
    return QFileInfo::exists(launchAgentPath());
#else
    return QFileInfo::exists(autostartDesktopPath());
#endif
}

QString autostartMechanismName()
{
#if defined(Q_OS_WIN)
    return QStringLiteral("Windows registry Run key");
#elif defined(Q_OS_MACOS)
    return QStringLiteral("macOS LaunchAgent");
#else
    return QStringLiteral("XDG autostart entry");
#endif
}

QString autostartLocation()
{
#if defined(Q_OS_WIN)
    return kWinRunKey + QStringLiteral("\\ForkMesh");
#elif defined(Q_OS_MACOS)
    return QDir::toNativeSeparators(launchAgentPath());
#else
    return QDir::toNativeSeparators(autostartDesktopPath());
#endif
}

QString systemdUserServiceUnitFromCgroup(const QByteArray &contents)
{
#if defined(Q_OS_LINUX)
    for (const QByteArray &line : contents.split('\n')) {
        const int pathStart = line.indexOf(":/");
        if (pathStart < 0)
            continue;
        const QList<QByteArray> components =
            line.mid(pathStart + 2).split('/');
        bool userManager = false;
        for (const QByteArray &component : components) {
            if (component.startsWith("user@") &&
                component.endsWith(".service")) {
                userManager = true;
                break;
            }
        }
        if (!userManager)
            continue;
        for (auto it = components.crbegin(); it != components.crend(); ++it) {
            if (it->endsWith(".service") &&
                !it->startsWith("user@")) {
                return QString::fromUtf8(*it);
            }
        }
    }
#else
    Q_UNUSED(contents);
#endif
    return {};
}

QString supervisingSystemdUserServiceUnit()
{
#if defined(Q_OS_LINUX)
    if (qgetenv("INVOCATION_ID").isEmpty())
        return {};
    QFile cgroup(QStringLiteral("/proc/self/cgroup"));
    if (!cgroup.open(QIODevice::ReadOnly | QIODevice::Text))
        return {};
    return systemdUserServiceUnitFromCgroup(cgroup.readAll());
#else
    return {};
#endif
}

QStringList systemdUserServiceCloseArguments(const QString &unit, bool restart)
{
    if (unit.isEmpty())
        return {};
    return {QStringLiteral("--user"),
            restart ? QStringLiteral("restart") : QStringLiteral("stop"),
            QStringLiteral("--no-block"), unit};
}

QString sourceGuardHoldPath()
{
    return forkmesh::paths::stateRoot() +
           QStringLiteral("/publisher/source-hold.json");
}

bool closeHoldsSourceGuard(const QString &unit, bool restart,
                           bool reopenAfterClose)
{
    return unit == QLatin1String(kSourceGuardUnit) && !restart &&
           !reopenAfterClose;
}

bool writeDesktopCloseHold(const QString &path, qint64 nowSeconds)
{
    if (!QDir().mkpath(QFileInfo(path).absolutePath()))
        return false;
    const QJsonObject record{
        {QStringLiteral("until"),
         static_cast<double>(nowSeconds + kDesktopCloseHoldSeconds)},
        {QStringLiteral("reason"),
         QStringLiteral("closed from the desktop window")},
        {QStringLiteral("setAt"), static_cast<double>(nowSeconds)},
        {QStringLiteral("setBy"), QStringLiteral("desktop")},
    };
    QSaveFile file(path);
    if (!file.open(QIODevice::WriteOnly))
        return false;
    file.write(QJsonDocument(record).toJson(QJsonDocument::Indented));
    return file.commit();
}

bool releaseDesktopCloseHold(const QString &path)
{
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly))
        return false;
    const QJsonObject record = QJsonDocument::fromJson(file.readAll()).object();
    file.close();
    if (record.value(QStringLiteral("setBy")).toString() !=
        QLatin1String("desktop"))
        return false;
    return QFile::remove(path);
}

static bool &userServiceRestartFlag()
{
    static bool requested = false;
    return requested;
}

bool requestSupervisingUserServiceRestart(const QString &relaunchPath)
{
    if (supervisingSystemdUserServiceUnit().isEmpty())
        return false;
    const QFileInfo target(relaunchPath);
    const QFileInfo self(QCoreApplication::applicationFilePath());
    const bool sameCanonical = !target.canonicalFilePath().isEmpty() &&
                               target.canonicalFilePath() ==
                                   self.canonicalFilePath();
    const bool samePath = QDir::cleanPath(target.absoluteFilePath()) ==
                          QDir::cleanPath(self.absoluteFilePath());
    if (!sameCanonical && !samePath)
        return false;
    userServiceRestartFlag() = true;
    return true;
}

bool supervisingUserServiceRestartRequested()
{
    return userServiceRestartFlag();
}

bool setAutostartEnabled(bool enabled)
{
    const QString exe = QCoreApplication::applicationFilePath();
#if defined(Q_OS_WIN)
    QSettings run(kWinRunKey, QSettings::NativeFormat);
    if (enabled)
        run.setValue("ForkMesh", QDir::toNativeSeparators(exe));
    else
        run.remove("ForkMesh");
    run.sync();
    return run.status() == QSettings::NoError &&
           run.contains("ForkMesh") == enabled;
#elif defined(Q_OS_MACOS)
    const QString path = launchAgentPath();
    if (!enabled) {
        return !QFileInfo::exists(path) || QFile::remove(path);
    }
    QDir().mkpath(QFileInfo(path).absolutePath());
    QFile file(path);
    if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate))
        return false;
    const QString plist = QStringLiteral(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
        "<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" "
        "\"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n"
        "<plist version=\"1.0\"><dict>\n"
        "  <key>Label</key><string>com.forkmesh.app</string>\n"
        "  <key>ProgramArguments</key><array><string>%1</string></array>\n"
        "  <key>RunAtLoad</key><true/>\n"
        "</dict></plist>\n").arg(exe);
    return file.write(plist.toUtf8()) >= 0;
#else
    const QString path = autostartDesktopPath();
    if (!enabled) {
        return !QFileInfo::exists(path) || QFile::remove(path);
    }
    QDir().mkpath(QFileInfo(path).absolutePath());
    QFile file(path);
    if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate))
        return false;
    const QString desktop = QStringLiteral(
        "[Desktop Entry]\n"
        "Type=Application\n"
        "Name=ForkMesh\n"
        "Exec=%1\n"
        "Terminal=false\n"
        "X-GNOME-Autostart-enabled=true\n").arg(exe);
    return file.write(desktop.toUtf8()) >= 0;
#endif
}

